examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchBlockEditor(
    label = "Meeting notes",
    state = state,
    modifier = Modifier.height(360.dp),
    blocks = setOf(
        MonarchBlockEditorBlockType.Heading2,
        MonarchBlockEditorBlockType.BulletedList,
        MonarchBlockEditorBlockType.Checklist,
    ),
    slashItems = listOf(MonarchSlashMenuItem(id = "date", label = "Today's date", group = "Insert")),
    onSlashItem = { item ->
        if (item.id == "date") {
            state.insertBlock(MonarchBlockEditorBlock.Text(MonarchBlockEditorState.newId(), text = "14 November"))
        }
    },
)

examples.setup:
val state = rememberMonarchBlockEditorState(
    listOf(
        MonarchBlockEditorBlock.Text("h", MonarchBlockEditorTextStyle.Heading2, "FAQ"),
        MonarchBlockEditorBlock.Toggle("q", "Why Friday?", body = "Support is staffed on the weekend.", expanded = false),
    ),
)
